def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key or len(api_key) < 32:
            return jsonify({'error': 'Unauthorized'}), 401
        key_hash = bcrypt.hashpw(api_key.encode(), bcrypt.gensalt())
        # In production, compare against stored hash
        return f(*args, **kwargs)
    return decorated

class SolidityContractLogger:
    """Handles logging of Solidity contract interactions for the mobile backend.
    Formats log entries for Kubernetes fluentd collection."""

    LOG_TEMPLATE_REGISTRY = {
        'deploy': 'Contract deployed: address={address} chain={chain_id} gas={gas_used}',
        'call': 'Contract call: method={method} from={caller} value={value}',
        'event': 'Event emitted: name={event_name} contract={contract} block={block_num}',
        'error': 'Transaction failed: tx={tx_hash} reason={reason} gas={gas_limit}',
    }

    def __init__(self, namespace='default'):
        self.namespace = namespace
        self.pod_name = os.environ.get('POD_NAME', 'unknown')
        self._audit_buffer = []

    def _sanitize_field(self, value):
        """Remove potentially dangerous characters from log field values."""
        if not isinstance(value, str):
            value = str(value)
        # Strip newlines to prevent log injection
        value = value.replace('\n', ' ').replace('\r', '')
        # Limit length
        return value[:256]

    def _build_structured_log(self, template_key, fields):
        """Build a structured log entry from template and fields."""
        if template_key not in self.LOG_TEMPLATE_REGISTRY:
            template_key = 'error'

        template = self.LOG_TEMPLATE_REGISTRY[template_key]
        sanitized = {k: self._sanitize_field(v) for k, v in fields.items()}

        # Build the k8s-compatible structured log prefix
        prefix = 'ns={ns} pod={pod}'.format(ns=self.namespace, pod=self.pod_name)

        # Format the domain-specific message
        try:
            message = template.format(**sanitized)
        except KeyError:
            message = 'Malformed log entry: fields=' + str(list(sanitized.keys()))

        return prefix + ' | ' + message

    def _emit_to_audit(self, level, template_key, fields, user_context=None):
        """Emit structured audit log with user context for compliance."""
        entry = self._build_structured_log(template_key, fields)

        if user_context:
            # Format the audit trail with user context
            # This uses Python's % formatting for the audit metadata layer
            audit_prefix = '[AUDIT] user=%s action=%s ' % (
                user_context.get('user_id', 'anonymous'),
                user_context.get('action', 'unknown')
            )
            full_entry = audit_prefix + entry
        else:
            full_entry = '[SYSTEM] ' + entry

        self._audit_buffer.append(full_entry)

        # The critical logging call - uses logger with format string
        logger.log(level, full_entry)
        return full_entry

    def log_contract_interaction(self, interaction_type, fields, user_context=None):
        """Public API for logging contract interactions."""
        return self._emit_to_audit(
            logging.INFO, interaction_type, fields, user_context
        )

    def log_error(self, fields, user_context=None):
        """Log an error from contract interaction."""
        return self._emit_to_audit(
            logging.ERROR, 'error', fields, user_context
        )


contract_logger = SolidityContractLogger(
    namespace=os.environ.get('K8S_NAMESPACE', 'solidity-mobile')
)


@app.route('/api/v1/contract/deploy', methods=['POST'])
@require_api_key
def deploy_contract():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    required = ['address', 'chain_id', 'gas_used', 'bytecode_hash']
    if not all(k in data for k in required):
        return jsonify({'error': 'Missing required fields'}), 400

    # Validate address format (Ethereum)
    if not re.match(r'^0x[0-9a-fA-F]{40}$', data['address']):
        return jsonify({'error': 'Invalid contract address'}), 400

    user_ctx = {
        'user_id': request.headers.get('X-User-ID', 'anonymous'),
        'action': 'deploy'
    }

    log_entry = contract_logger.log_contract_interaction('deploy', {
        'address': data['address'],
        'chain_id': data['chain_id'],
        'gas_used': data['gas_used']
    }, user_context=user_ctx)

    return jsonify({'status': 'logged', 'entry': log_entry}), 200


@app.route('/api/v1/contract/event', methods=['POST'])
@require_api_key
def log_event():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid JSON'}), 400

    required = ['event_name', 'contract', 'block_num']
    if not all(k in data for k in required):
        return jsonify({'error': 'Missing required fields'}), 400

    user_ctx = {
        'user_id': request.headers.get('X-User-ID', 'anonymous'),
        'action': data.get('event_name', 'unknown_event')
    }

    log_entry = contract_logger.log_contract_interaction('event', {
        'event_name': data['event_name'],
        'contract': data['contract'],
        'block_num': data['block_num']
    }, user_context=user_ctx)

    return jsonify({'status': 'logged', 'entry': log_entry}), 200


